CREATE TABLE IF NOT EXISTS gym_user (id VARCHAR(36) PRIMARY KEY, username VARCHAR(40) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS user_routine (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES gym_user(id), name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS user_exercise (id VARCHAR(36) PRIMARY KEY, routine_id VARCHAR(36) NOT NULL REFERENCES user_routine(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, target_sets INT NOT NULL, target_reps INT NOT NULL, reps_max INT NOT NULL, unit VARCHAR(10) NOT NULL, per_side BOOLEAN NOT NULL, rir VARCHAR(10) NOT NULL, position INT NOT NULL);
CREATE TABLE IF NOT EXISTS user_workout (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES gym_user(id), routine_name VARCHAR(80) NOT NULL, trained_on DATE NOT NULL, notes VARCHAR(1000) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS user_logged_set (workout_id VARCHAR(36) NOT NULL REFERENCES user_workout(id) ON DELETE CASCADE, exercise_name VARCHAR(100) NOT NULL, position INT NOT NULL, weight DECIMAL(7,2) NOT NULL, reps INT NOT NULL, unit VARCHAR(10) NOT NULL, per_side BOOLEAN NOT NULL, rir INT NOT NULL, PRIMARY KEY (workout_id,position));
CREATE TABLE IF NOT EXISTS schedule (user_id VARCHAR(36) NOT NULL REFERENCES gym_user(id), planned_on DATE NOT NULL, routine_id VARCHAR(36) REFERENCES user_routine(id) ON DELETE CASCADE, PRIMARY KEY(user_id,planned_on));
CREATE TABLE IF NOT EXISTS weekly_plan (user_id VARCHAR(36) NOT NULL REFERENCES gym_user(id), weekday INT NOT NULL, routine_id VARCHAR(36) REFERENCES user_routine(id) ON DELETE CASCADE, PRIMARY KEY(user_id,weekday));
